// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController, IAccessControl, IERC165} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes4 interfaceId) public {
        // Rule (universal): c is an ERC165-conformant AccessControl, so for EVERY
        // interfaceId it reports support exactly for the IAccessControl interface id
        // and the IERC165 interface id. In particular, querying the IAccessControl id
        // must yield true. The mutant tests for the IERC165 id in place of the
        // IAccessControl id, so it answers false for the IAccessControl id.
        bytes4 accessControlId = type(IAccessControl).interfaceId;
        bool ok;
        try c.supportsInterface(accessControlId) returns (bool supported) {
            ok = supported;
        } catch {
            ok = false;
        }
        assertTrue(ok, "supportsInterface(IAccessControl.interfaceId) must be true");
    }
}
